sys_script.script:
// Adventure Summariser Processing Business Rule
// Triggers when adventure record is created or updated

try {
    // Check if auto-processing is enabled
    if (!gs.getProperty('adventure_summariser.auto_process', 'true') === 'true') {
        gs.info('AdventureSummariser: Auto-processing is disabled');
        return;
    }

    // Only process if this is a new record or if AI summary is empty
    if (current.ai_summary.nil() || current.ai_summary.toString() === '') {
        gs.info('AdventureSummariser: Processing adventure: ' + current.getUniqueValue());

        // Initialize workflow
        var workflow = new AdventureSummariserWorkflow();

        // Process the adventure
        workflow.onAdventureChange(current, previous);

    } else {
        gs.info('AdventureSummariser: Adventure already has AI summary, skipping processing');
    }

} catch (e) {
    gs.error('AdventureSummariser: Error in business rule: ' + e.message);
}
